def reserve(seat_id, user_id):
    with db.transaction():
        row = db.query('SELECT status FROM seats WHERE id = %s FOR UPDATE', seat_id)
        if row.status != 'free':
            raise SeatTaken()
        db.execute('UPDATE seats SET status = %s, holder = %s WHERE id = %s', 'held', user_id, seat_id)

def on_order_paid(order):
    send_confirmation(order)

def on_payment_webhook(evt):
    order = Order.get(evt.order_id)
    on_order_paid(order)  # webhook may be delivered more than once; no idempotency check

def compute_order_total(items, tax_rate):
    subtotal = sum(i.price * i.qty for i in items)
    return subtotal * (1 + tax_rate)

